namespace Shop;

public enum CustomerType { Regular, Loyal, Student, Partner }

public record OrderLine(string Sku, decimal UnitPrice, int Quantity);

public record Order(CustomerType Customer, IReadOnlyList<OrderLine> Lines);

// A customer type's discount: the amount off a subtotal, and the line shown on the receipt.
public record DiscountRule(string ReceiptLine, Func<decimal, decimal> AmountOff);

public static class Discounts
{
    // Adding a customer type: add the enum value and one entry here.
    public static DiscountRule For(CustomerType customer) => customer switch
    {
        CustomerType.Regular => new("Regular: no discount", _ => 0m),
        CustomerType.Loyal => new("Loyal: 5% off", s => s * 0.05m),
        CustomerType.Student => new("Student: 10% off, max 30", s => Math.Min(s * 0.10m, 30m)),
        CustomerType.Partner => new("Partner: 10% off, 15% off above 1,000",
            s => s > 1000m ? s * 0.15m : s * 0.10m),
        _ => throw new ArgumentOutOfRangeException(nameof(customer), customer, "No discount rule defined.")
    };
}

public static class PriceCalculator
{
    public static decimal Subtotal(Order order) => order.Lines.Sum(l => l.UnitPrice * l.Quantity);

    public static decimal Total(Order order)
    {
        var subtotal = Subtotal(order);
        return subtotal - Discounts.For(order.Customer).AmountOff(subtotal);
    }

    public static string DiscountReceiptLine(Order order) => Discounts.For(order.Customer).ReceiptLine;
}

